    [Fact]
    [Trait("Journey", "D19-G")]
    public void TheBuildToolingWritesTheReferencesAndTheManifestFromThisBuild()
    {
        string output = CliHarness.TempDirectory("docs-generate");
        try
        {
            (int code, string text) = Tool(() => ReferenceSet.Generate(output, Declaration(output), json: true));
            Assert.True(code == 0, text);
            Assert.Equal(ReferenceSet.ReleaseVersion, JsonDocument.Parse(text).RootElement.GetProperty("version").GetString());
            foreach (string name in new[] { "cli-reference.md", "api-reference.md", "record-reference.md", "manifest.json", "reference-inventory.json" })
            {
                Assert.True(File.Exists(Path.Combine(output, name)), name);
            }

            using JsonDocument manifest = JsonDocument.Parse(File.ReadAllBytes(Path.Combine(output, "manifest.json")));
            Assert.Equal("reference-inventory.json", manifest.RootElement.GetProperty("referenceInventory").GetString());
            using JsonDocument inventory = JsonDocument.Parse(File.ReadAllBytes(Path.Combine(output, "reference-inventory.json")));
            Assert.Equal("vericairn.reference-inventory/1", inventory.RootElement.GetProperty("format").GetString());
            Assert.Equal(manifest.RootElement.GetProperty("commit").GetString(), inventory.RootElement.GetProperty("commit").GetString());
            foreach (JsonElement reference in inventory.RootElement.GetProperty("references").EnumerateArray())
                Assert.Equal(reference.GetProperty("hash").GetString(), Vericairn.Records.Hashing.ContentHash.Sha256File(Path.Combine(output, reference.GetProperty("path").GetString()!)));
            List<string> commands = manifest.RootElement.GetProperty("commands").EnumerateArray().Select(c => c.GetString()!).ToList();
            Assert.Contains("docs check", commands);
            Assert.Contains("docs pin", commands);
            Assert.Contains("POST /v1/documents/pin", manifest.RootElement.GetProperty("operations").EnumerateArray().Select(o => o.GetString()));
            string pinReference = File.ReadAllText(Path.Combine(output, "cli-reference.md"));
            int pinStart = pinReference.IndexOf(" `vericairn docs pin`\n", StringComparison.Ordinal);
            Assert.True(pinStart >= 0);
            int pinEnd = pinReference.IndexOf("\n#", pinStart + 1, StringComparison.Ordinal);
            string pinSection = System.Net.WebUtility.HtmlDecode(pinEnd < 0 ? pinReference[pinStart..] : pinReference[pinStart..pinEnd]);
            foreach (string option in new[] { "--by", "--summary", "--title", "--expected" }) Assert.Contains(option, pinSection, StringComparison.Ordinal);
            Assert.Contains("exact estate file bytes", pinSection, StringComparison.Ordinal);
            Assert.Contains("forks", pinSection, StringComparison.Ordinal);
            Assert.Contains("docs companions", commands);
            Assert.Contains("docs render", commands);
            foreach (string route in new[] { "/v1/companions", "/v1/companions/render", "/v1/companions/sources", "/v1/companions/compare" })
                Assert.Contains("GET " + route, manifest.RootElement.GetProperty("operations").EnumerateArray().Select(o => o.GetString()));
            Assert.DoesNotContain("docs generate", commands);
            Assert.Contains("release providers", commands);
            Assert.Contains("records new", commands);
            Assert.Contains("estate upgrade", commands);
            Assert.Contains("updates configure", commands);
            foreach (string action in new[] { "push", "open", "merge", "observe" })
            {
                Assert.Contains("changes " + action, commands);
                Assert.Contains("POST /v1/changes/" + action, manifest.RootElement.GetProperty("operations").EnumerateArray().Select(o => o.GetString()));
            }
            foreach (string action in new[] { "observe", "unlist", "deprecate" })
            {
                Assert.Contains("packages " + action, commands);
                Assert.Contains("POST /v1/packages/" + action, manifest.RootElement.GetProperty("operations").EnumerateArray().Select(o => o.GetString()));
            }
            Assert.Contains("GET /v1/providers", manifest.RootElement.GetProperty("operations").EnumerateArray().Select(o => o.GetString()));
            Assert.Contains("work-order", manifest.RootElement.GetProperty("recordTypes").EnumerateArray().Select(t => t.GetString()));
            Assert.Contains("operator list", commands);
            Assert.Contains("GET /v1/operator/actions", manifest.RootElement.GetProperty("operations").EnumerateArray().Select(o => o.GetString()));
            Assert.Equal(13, manifest.RootElement.GetProperty("documents").GetArrayLength());

            // The record formats of the build, which the release observer reads from the set as the release's own.
            JsonElement formats = manifest.RootElement.GetProperty("recordFormat");
            Assert.Equal(RecordFormats.Reads, formats.GetProperty("reads").EnumerateArray().Select(f => f.GetInt64()));
            Assert.Equal(RecordFormats.Current, formats.GetProperty("writes").GetInt64());

            string cli = System.Net.WebUtility.HtmlDecode(File.ReadAllText(Path.Combine(output, "cli-reference.md")));
            Assert.Contains("## `vericairn records`", cli, StringComparison.Ordinal);
            Assert.Contains("### `vericairn records new`", cli, StringComparison.Ordinal);
            Assert.Contains("`--by <by>`", cli, StringComparison.Ordinal);
            Assert.Contains("### `vericairn operator list`", cli, StringComparison.Ordinal);
            Assert.Contains("### `vericairn updates configure`", cli, StringComparison.Ordinal);
            Assert.Contains("`--enabled <enabled>`", cli, StringComparison.Ordinal);
            Assert.Contains("Disclosure and upgrade notices go to stderr", cli, StringComparison.Ordinal);

            // A command's own --version, the version to release, is documented; built-in options are documented at the root.
            string submit = cli[cli.IndexOf("### `vericairn release submit`", StringComparison.Ordinal)..];
            submit = submit[..submit.IndexOf("\n### ", 5, StringComparison.Ordinal)];
            Assert.Contains("`--version <version>`", submit, StringComparison.Ordinal);
            Assert.DoesNotContain("--help", submit, StringComparison.Ordinal);
            string rootOptions = cli[..cli.IndexOf("## `vericairn ", StringComparison.Ordinal)];
            Assert.Contains("--recipient <recipient>", rootOptions, StringComparison.Ordinal);
            Assert.Contains("--for-assignment <for-assignment>", rootOptions, StringComparison.Ordinal);
            Assert.Contains("--depth <depth>", rootOptions, StringComparison.Ordinal);
            Assert.DoesNotContain(Directory.GetCurrentDirectory(), cli, StringComparison.Ordinal);
            string api = File.ReadAllText(Path.Combine(output, "api-reference.md"));
            Assert.Contains("## `POST /v1/records`", api, StringComparison.Ordinal);
            Assert.Contains("| /parameters/0/name | id |", System.Net.WebUtility.HtmlDecode(api), StringComparison.Ordinal);
            Assert.Contains("| /parameters/0/in | path |", System.Net.WebUtility.HtmlDecode(api), StringComparison.Ordinal);
            Assert.All(api.Split('\n'), line => Assert.Equal(line.TrimEnd(), line));
            Assert.Contains("## `acceptance`", File.ReadAllText(Path.Combine(output, "record-reference.md")), StringComparison.Ordinal);
        }
        finally
        {
            Directory.Delete(output, recursive: true);
        }
    }

    [Fact]
    [Trait("Journey", "D19-G")]
    public void ANewFixtureSetCanBeFrozenWithoutChangingTheEarlierSetOrItsDigests()
    {
        string root = CliHarness.TempDirectory("companion-frozen-sets");
        try
        {
            string earlier = Path.Combine(root, "0.1.0"), next = Path.Combine(root, "0.2.0");
            Directory.CreateDirectory(earlier);
            string oldFile = Path.Combine(earlier, "reference.md");
            File.WriteAllText(oldFile, "# Earlier retained fixture\n");
            byte[] oldBytes = File.ReadAllBytes(oldFile);
            string oldHash = Vericairn.Records.Hashing.ContentHash.Sha256(oldBytes);
            var sets = new Dictionary<string, Dictionary<string, string>>(StringComparer.Ordinal)
            {
                ["0.1.0"] = new(StringComparer.Ordinal) { ["reference.md"] = oldHash },
            };
            string index = Path.Combine(root, "frozen-sha256.json");
            File.WriteAllText(index, JsonSerializer.Serialize(new { format = "vericairn.frozen-docs/1", sets }));
            string declaration = Declaration(next);
            (int generated, string details) = Tool(() => ReferenceSet.Generate(next, declaration, json: true));
            Assert.True(generated == 0, details);
            Assert.Equal(0, Tool(() => ReferenceSet.CompareWithBuild(next, json: true)).Code);
            sets["0.2.0"] = Directory.EnumerateFiles(next, "*", SearchOption.AllDirectories).ToDictionary(
                p => Path.GetRelativePath(next, p).Replace('\\', '/'), Vericairn.Records.Hashing.ContentHash.Sha256File, StringComparer.Ordinal);
            File.WriteAllText(index, JsonSerializer.Serialize(new { format = "vericairn.frozen-docs/1", sets }));
            byte[] frozen = File.ReadAllBytes(index);
            Assert.NotEqual(0, Tool(() => ReferenceSet.Generate(earlier, declaration, json: true)).Code);
            Assert.NotEqual(0, Tool(() => ReferenceSet.Generate(next, declaration, json: true)).Code);
            Assert.Equal(frozen, File.ReadAllBytes(index));
            Assert.Equal(oldBytes, File.ReadAllBytes(oldFile));
            Assert.Equal(oldHash, sets["0.1.0"]["reference.md"]);
            Assert.All(sets["0.2.0"], member => Assert.Equal(member.Value,
                Vericairn.Records.Hashing.ContentHash.Sha256File(Path.Combine(next, member.Key))));
        }
        finally { CliHarness.Delete(root); }
    }

