    [Fact]
    public void CheckAcceptsACompleteSetAndNamesEveryGapOfAnIncompleteOne()
    {
        string output = CliHarness.TempDirectory("docs-check");
        try
        {
            string declaration = Declaration(output);
            Assert.Equal(0, Tool(() => ReferenceSet.Generate(output, declaration, json: false)).Code);
            foreach (string name in Authored)
            {
                File.WriteAllText(Path.Combine(output, name), $"# {name} for Vericairn {ReferenceSet.ReleaseVersion}\n\nAuthored.\n");
            }

            CliHarness.Outcome complete = CliHarness.Run("docs", "check", output, "--documents", declaration);
            Assert.True(complete.Code == 0, complete.Out + complete.Err);
            Assert.Contains("complete: 0 errors", complete.Out, StringComparison.Ordinal);

            File.Delete(Path.Combine(output, "install.md"));
            File.WriteAllText(Path.Combine(output, "README.md"), "# A set that forgot its version\n");
            string cliPath = Path.Combine(output, "cli-reference.md");
            File.WriteAllLines(cliPath, File.ReadAllLines(cliPath).Where(l => !l.Contains("`vericairn docs check`", StringComparison.Ordinal)));
            string recordPath = Path.Combine(output, "record-reference.md");
            File.WriteAllLines(recordPath, File.ReadAllLines(recordPath).Where(l => !l.Contains("## `acceptance`", StringComparison.Ordinal)));

            CliHarness.Outcome incomplete = CliHarness.Run("--json", "docs", "check", output);
            Assert.Equal(1, incomplete.Code);
            JsonElement findings = incomplete.Json;
            Assert.Equal(5, findings.GetProperty("errors").GetInt32());
            List<string> messages = findings.GetProperty("findings").EnumerateArray().Select(f => f.GetProperty("Location").GetString() + ": " + f.GetProperty("Message").GetString()).ToList();
            Assert.Contains(messages, m => m.StartsWith("install.md: Missing", StringComparison.Ordinal));
            Assert.Contains(messages, m => m.StartsWith("README.md: Does not name the version", StringComparison.Ordinal));
            Assert.Contains(messages, m => m.StartsWith("cli-reference.md: No heading for `vericairn docs check`", StringComparison.Ordinal));
            Assert.Contains(messages, m => m.StartsWith("record-reference.md: No heading for `acceptance`", StringComparison.Ordinal));
            Assert.Contains(messages, m => m.StartsWith("reference-inventory.json: A generated reference hash differs", StringComparison.Ordinal));

            // A manifest that drops a document the product declares is refused against the declaration.
            string manifestPath = Path.Combine(output, "manifest.json");
            File.WriteAllText(manifestPath, File.ReadAllText(manifestPath).Replace("\"mcp.md\",", string.Empty, StringComparison.Ordinal));
            CliHarness.Outcome dropped = CliHarness.Run("docs", "check", output, "--documents", declaration);
            Assert.Contains("declares mcp.md", dropped.Out, StringComparison.Ordinal);
        }
        finally
        {
            Directory.Delete(output, recursive: true);
        }
    }

    [Fact]
    public void TheToolingRefusesAManifestThatDisagreesWithThisBuild()
    {
        string output = CliHarness.TempDirectory("docs-stale");
        try
        {
            Assert.Equal(0, Tool(() => ReferenceSet.Generate(output, Declaration(output), json: false)).Code);
            Assert.Equal(0, Tool(() => ReferenceSet.CompareWithBuild(output, json: false)).Code);
            string manifestPath = Path.Combine(output, "manifest.json");
            string manifest = File.ReadAllText(manifestPath).Replace("\"docs check\"", "\"docs retired-verb\"", StringComparison.Ordinal);
            File.WriteAllText(manifestPath, manifest);

            (int code, string text) = Tool(() => ReferenceSet.CompareWithBuild(output, json: false));
            Assert.Equal(1, code);
            Assert.Contains("This build has the command vericairn docs check and the set does not", text, StringComparison.Ordinal);
            Assert.Contains("The set documents the command vericairn docs retired-verb, which this build does not have", text, StringComparison.Ordinal);

            // Record formats other than this build's, or none, are refused too: the release observer records what the set states.
            string writes = $"\"writes\": {RecordFormats.Current}";
            Assert.Contains(writes, manifest, StringComparison.Ordinal);
            File.WriteAllText(manifestPath, manifest.Replace(writes, "\"writes\": 1", StringComparison.Ordinal));
            (code, text) = Tool(() => ReferenceSet.CompareWithBuild(output, json: false));
            Assert.Equal(1, code);
            string reads = string.Join(", ", RecordFormats.Reads);
            Assert.Contains($"The set states that the release reads record formats {reads} and writes 1, and this build reads record formats {reads} and writes {RecordFormats.Current}", text, StringComparison.Ordinal);
            using (JsonDocument stale = JsonDocument.Parse(manifest))
            {
                File.WriteAllText(manifestPath, JsonSerializer.Serialize(stale.RootElement.EnumerateObject().Where(p => p.Name != "recordFormat").ToDictionary(p => p.Name, p => p.Value)));
            }

            (code, text) = Tool(() => ReferenceSet.CompareWithBuild(output, json: false));
            Assert.Equal(1, code);
            Assert.Contains($"This build reads record formats {reads} and writes {RecordFormats.Current}, and the set states no record formats", text, StringComparison.Ordinal);
        }
        finally
        {
            Directory.Delete(output, recursive: true);
        }
    }

    [Theory]
    [InlineData("missing")]
    [InlineData("commit")]
    [InlineData("hash")]
    [InlineData("duplicate")]
    [InlineData("declaration")]
    public void ExistingBuildAndDocumentChecksRefuseAnInvalidReferenceInventory(string defect)
    {
        string output = CliHarness.TempDirectory("docs-inventory");
        try
        {
            Assert.Equal(0, Tool(() => ReferenceSet.Generate(output, Declaration(output), json: false)).Code);
            foreach (string name in Authored) File.WriteAllText(Path.Combine(output, name), "# " + ReferenceSet.ReleaseVersion + "\n");
            string path = Path.Combine(output, "reference-inventory.json");
            var inventory = System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(path))!.AsObject();
            if (defect == "commit") inventory["commit"] = new string('0', 40);
            if (defect == "hash") inventory["references"]![0]!["hash"] = "sha256:" + new string('0', 64);
            if (defect == "duplicate") inventory["items"]!.AsArray().Add(inventory["items"]![0]!.DeepClone());
            File.WriteAllText(path, inventory.ToJsonString());
            if (defect == "missing") File.Delete(path);
            if (defect == "declaration")
            {
                string manifestPath = Path.Combine(output, "manifest.json");
                var manifest = System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(manifestPath))!.AsObject();
                manifest.Remove("referenceInventory"); File.WriteAllText(manifestPath, manifest.ToJsonString());
            }
            (int code, string text) = Tool(() => ReferenceSet.CompareWithBuild(output, json: false));
            Assert.Equal(1, code);
            Assert.Contains("docs.reference-inventory", text, StringComparison.Ordinal);
            CliHarness.Outcome check = CliHarness.Run("docs", "check", output);
            Assert.Equal(1, check.Code);
            Assert.Contains("docs.reference-inventory", check.Out, StringComparison.Ordinal);
        }
        finally { Directory.Delete(output, recursive: true); }
    }

    [Fact]
    public void TheNotesBeginWhereThePreviousSetsNotesEndedAndRecordTheirWindow()
    {
        string root = CliHarness.TempDirectory("notes-window");
        string scratch = CliHarness.TempDirectory("notes-window-scratch");
        try
        {
            string op = CliHarness.Ok("--estate", root, "--json", "estate", "init", "--name", "Example", "--slug", "example", "--purpose", "Release notes.", "--operator-name", "Operator", "--organization", "Example", "--commit", "0123456789abcdef0123456789abcdef01234567").Json.GetProperty("operator").GetString()!;
            string product = CliHarness.Ok("--estate", root, "--json", "records", "new", "product", "--by", op, "--body", CliHarness.WriteJson(scratch, "product.json", """{"name":"Widget","slug":"widget","summary":"A widget.","editions":[{"name":"Community","slug":"community","summary":"Free."}],"surfaces":[{"name":"CLI","slug":"cli","summary":"Command line."}]}""")).Id;

            // The 0.1.0 notes were made at 00:30, before its build; W-1 was recorded after them and before the 0.1.0 publication at 01:02.
            WorkOrder(root, scratch, op, "W-0", "2026-09-01T00:10:00Z");
            WorkOrder(root, scratch, op, "W-1", "2026-09-01T00:45:00Z");
            string release = $$"""{"version":"0.1.0","repository":"Example/widget","commit":"0123456789abcdef0123456789abcdef01234567","status":"candidate","artifacts":[{"name":"widget-0.1.0-linux-x64.zip","hash":"sha256:{{new string('1', 64)}}","bytes":10,"platform":"linux-x64"}],"recordFormat":{"reads":[1,2],"writes":2},"evidence":[],"qualified":[],"signing":"unsigned developer build","limitations":[]}""";
            CliHarness.Outcome candidate = CliHarness.Ok("--estate", root, "--json", "records", "new", "release", "--by", op, "--subject", $"product:{product}", "--at", "2026-09-01T01:00:00Z", "--body", CliHarness.WriteJson(scratch, "candidate.json", release));
            string releaseAcceptance = CliHarness.Ok("--estate", root, "--json", "records", "new", "acceptance", "--by", op, "--subject", $"release:{candidate.Id}:{candidate.Hash}", "--at", "2026-09-01T01:01:00Z", "--body", CliHarness.WriteJson(scratch, "accept.json", """{"statement":"Accepted 0.1.0.","basis":[],"self":true}""")).Id;
            CliHarness.Ok("--estate", root, "--json", "records", "new", "release", "--by", op, "--subject", $"product:{product}", "--supersedes", candidate.Id, "--at", "2026-09-01T01:02:00Z", "--body", CliHarness.WriteJson(scratch, "published.json", release.Replace("\"status\":\"candidate\"", "\"status\":\"published\",\"publishedAt\":\"2026-09-01T01:02:00Z\",\"url\":\"https://example.invalid/releases/0.1.0\"", StringComparison.Ordinal)));
            WorkOrder(root, scratch, op, "W-2", "2026-09-01T02:00:00Z");

            // Ordinary work can be self-accepted by a builder with authority, but it stays out of release acceptances.
            string builder = CliHarness.Ok("--estate", root, "--json", "records", "new", "principal", "--by", op, "--body", CliHarness.WriteJson(scratch, "builder.json", """{"kind":"agent","name":"Builder","roles":["builder"],"agent":{"vendor":"Example","product":"Example Agent"}}""")).Id;
            string decision = CliHarness.Ok("--estate", root, "--json", "records", "new", "decision", "--by", op, "--body", CliHarness.WriteJson(scratch, "decision.json", $$"""{"title":"Ordinary work","stake":"low","notAuthorized":[],"statement":"The builder may accept its ordinary work.","summary":"Ordinary work delegation.","synthesis":"Release acceptance remains with the operator.","effects":["Grant ordinary work self-acceptance."],"affects":[],"decidedBy":"{{op}}","decidedAt":"2026-09-01T02:00:00Z"}""")).Id;
            CliHarness.Ok("--estate", root, "--json", "records", "new", "authority", "--by", op, "--body", CliHarness.WriteJson(scratch, "authority.json", $$"""{"grantee":"{{builder}}","scope":["self-accept-ordinary-work"],"reserved":[],"conditions":[],"basis":"{{decision}}"}"""));
            CliHarness.Outcome ordinary = WorkOrder(root, scratch, builder, "W-3", RecordParser.FormatTimestamp(DateTimeOffset.UtcNow));
            string ordinaryAcceptance = CliHarness.Ok("--estate", root, "--json", "records", "new", "acceptance", "--by", builder, "--subject", $"work-order:{ordinary.Id}:{ordinary.Hash}", "--body", CliHarness.WriteJson(scratch, "self-accept.json", """{"statement":"Accepted ordinary work.","basis":[],"self":true}""")).Id;

            // A format-2 admission has no legacy scope; its notes must not invent an empty scope label.
            string device = CliHarness.Ok("--estate", root, "--json", "devices", "create", "--principal", op, "--name", "Notes device", "--custody", "file").Id;
            string admission = CliHarness.Ok("--estate", root, "--json", "devices", "admit", device, "--by", op, "--note", "Admission for the notes.").Id;
            DateTimeOffset reading = DateTimeOffset.UtcNow.AddSeconds(2);

            // The previous set records the window of its notes: these begin at its end, so W-1 is in them, and they record their own.
            string sets = Path.Combine(scratch, "releases");
            Directory.CreateDirectory(Path.Combine(sets, "0.1.0"));
            File.WriteAllText(Path.Combine(sets, "0.1.0", "manifest.json"), """{"format":"vericairn.docs/1","version":"0.1.0","notes":{"from":"2026-08-01T00:00:00Z","to":"2026-09-01T00:30:00Z"}}""");
            string output = Path.Combine(sets, "0.2.0");
            (int code, string text) = Tool(() => Docs.Notes(root, "0.1.0", "0.2.0", output, null, json: true, at: reading));
            Assert.Equal(0, code);
            var written = new CliHarness.Outcome(code, text, string.Empty);
            Assert.Equal("2026-09-01T00:30:00Z", written.Json.GetProperty("window").GetProperty("from").GetString());
            string notes = File.ReadAllText(Path.Combine(output, "release-notes.md"));
            Assert.Contains("from the estate's records since the end of the notes of 0.1.0 (2026-09-01 00:30 UTC) up to ", notes, StringComparison.Ordinal);
            Assert.DoesNotContain("**W-0**", notes, StringComparison.Ordinal);
            Assert.Contains("**W-1**", notes, StringComparison.Ordinal);
            Assert.Contains("**W-2**", notes, StringComparison.Ordinal);
            Assert.Contains($"Device admitted to author records ({admission}).", notes, StringComparison.Ordinal);
            Assert.DoesNotContain("scope  (", notes, StringComparison.Ordinal);
            Assert.Contains("## The release itself\n\nNone in this window.", notes, StringComparison.Ordinal);
            Assert.Contains("## Other releases recorded in this window\n\n- 0.1.0 candidate", notes, StringComparison.Ordinal);
            Assert.Contains("- 0.1.0 published", notes, StringComparison.Ordinal);
            string acceptances = notes.Split("## Milestone and release acceptances\n", StringSplitOptions.None)[1].Split("\n## ", StringSplitOptions.None)[0];
            Assert.Contains($"release 0.1.0: \"Accepted 0.1.0.\" (acceptance {releaseAcceptance},", acceptances, StringComparison.Ordinal);
            Assert.DoesNotContain(ordinaryAcceptance, acceptances, StringComparison.Ordinal);
            JsonElement window = JsonDocument.Parse(File.ReadAllText(Path.Combine(output, "manifest.json"))).RootElement.GetProperty("notes");
            Assert.Equal("2026-09-01T00:30:00Z", window.GetProperty("from").GetString());
            Assert.True(string.CompareOrdinal(window.GetProperty("to").GetString(), "2026-09-01T02:00:00Z") >= 0);
            Assert.Equal(RecordParser.FormatTimestamp(reading.AddSeconds(-1)), window.GetProperty("to").GetString());

            // The build tooling, generating the set's references again, keeps the window the notes recorded.
            Assert.Equal(0, Tool(() => ReferenceSet.Generate(output, Declaration(output), json: false)).Code);
            using (JsonDocument regenerated = JsonDocument.Parse(File.ReadAllText(Path.Combine(output, "manifest.json"))))
            {
                Assert.Equal(window.GetRawText(), regenerated.RootElement.GetProperty("notes").GetRawText());
                Assert.True(regenerated.RootElement.TryGetProperty("commands", out _));
            }

            CheckExplicitNotesStart(root, output);

            // A set made before the window was recorded gives the end its notes state, to the minute.
            File.WriteAllText(Path.Combine(sets, "0.1.0", "manifest.json"), """{"format":"vericairn.docs/1","version":"0.1.0"}""");
            File.WriteAllText(Path.Combine(sets, "0.1.0", "release-notes.md"), "# Release notes, Vericairn 0.1.0\n\nPrepared by `vericairn docs notes` before the release build (one entry moved after generation), from the estate's records since the publication of 0.0.9 (2026-08-01 00:00 UTC) up to 2026-09-01 00:30 UTC; the records are the source and this page is a rendering.\n\n## What the release contains\n\nUp to 2026-09-01 01:00 UTC; the records are the source of nothing here.\n");
            CliHarness.Ok("--estate", root, "docs", "notes", "--from", "0.1.0", "--to", "0.2.0", "--out", output + Path.DirectorySeparatorChar);
            notes = File.ReadAllText(Path.Combine(output, "release-notes.md"));
            Assert.Contains("since 2026-09-01 00:30 UTC (where the notes of 0.1.0 end, as they state it to the minute, so a record of that minute may be in both) up to ", notes, StringComparison.Ordinal);
            Assert.Contains("**W-1**", notes, StringComparison.Ordinal);
            Assert.DoesNotContain("**W-0**", notes, StringComparison.Ordinal);

            CheckExplicitNotesStart(root, output);

            // An unreadable end cannot prove that an explicit start leaves no gap; with no previous set the publication bounds it.
            File.WriteAllText(Path.Combine(sets, "0.1.0", "release-notes.md"), "# Release notes, Vericairn 0.1.0\n\nWritten by hand.\n");
            CliHarness.Outcome unread = CliHarness.Run("--estate", root, "docs", "notes", "--from", "0.1.0", "--to", "0.2.0", "--out", output);
            Assert.Equal(2, unread.Code);
            Assert.Contains("--since", unread.Err, StringComparison.Ordinal);
            CliHarness.Outcome unverifiable = CliHarness.Run("--estate", root, "docs", "notes", "--from", "0.1.0", "--to", "0.2.0", "--out", output, "--since", "2026-09-01T00:40:00Z");
            Assert.Equal(2, unverifiable.Code);
            Assert.Contains("cannot verify", unverifiable.Err, StringComparison.Ordinal);
            Assert.Equal(2, CliHarness.Run("--estate", root, "docs", "notes", "--from", "0.1.0", "--to", "0.2.0", "--out", output, "--since", "2026-09-01 00:40").Code);
            string elsewhere = Path.Combine(scratch, "elsewhere", "0.2.0");
            CliHarness.Ok("--estate", root, "docs", "notes", "--from", "0.1.0", "--to", "0.2.0", "--out", elsewhere);
            notes = File.ReadAllText(Path.Combine(elsewhere, "release-notes.md"));
            Assert.Contains("since the publication of 0.1.0 (2026-09-01 01:02 UTC; no documentation set of 0.1.0 beside this one says where its notes ended) up to ", notes, StringComparison.Ordinal);
            Assert.DoesNotContain("**W-1**", notes, StringComparison.Ordinal);
            Assert.DoesNotContain(scratch, notes, StringComparison.Ordinal);
        }
        finally
        {
            CliHarness.Delete(root, scratch);
        }
    }

    [Theory]
    [InlineData("0.2.0")]
    [InlineData("0.3.0")]
    [InlineData("0.3.1")]
    [InlineData("0.4.0")]
    [InlineData("0.4.1")]
    [InlineData("0.4.2")]
    public void TheReleasedSetsAreComplete(string version)
    {
        string? root = AppContext.BaseDirectory;
        while (root is not null && !File.Exists(Path.Combine(root, "Vericairn.slnx")))
        {
            root = Path.GetDirectoryName(root);
        }

        Assert.NotNull(root);
        string set = Path.Combine(root, "docs", "releases", version);
        CliHarness.Outcome outcome = CliHarness.Run("docs", "check", set);
        Assert.True(outcome.Code == 0, outcome.Out + outcome.Err);
        Assert.Contains("complete: 0 errors", outcome.Out, StringComparison.Ordinal);
    }

    private static CliHarness.Outcome WorkOrder(string root, string scratch, string by, string key, string at) =>
        CliHarness.Ok("--estate", root, "--json", "records", "new", "work-order", "--by", by, "--at", at, "--body", CliHarness.WriteJson(scratch, key + ".json", $$"""{"key":"{{key}}","kind":"ordinary","title":"Work {{key}}","intent":"Exercise the notes.","scope":["notes"],"exitQuestion":"Done?","inputs":[],"deliverables":["notes"]}"""));

    private static void CheckExplicitNotesStart(string root, string output)
    {
        string manifest = File.ReadAllText(Path.Combine(output, "manifest.json"));
        string notes = File.ReadAllText(Path.Combine(output, "release-notes.md"));
        CliHarness.Outcome later = CliHarness.Run("--estate", root, "docs", "notes", "--from", "0.1.0", "--to", "0.2.0", "--out", output, "--since", "2026-09-01T00:30:01Z");
        Assert.Equal(2, later.Code);
        Assert.Contains("later than the previous set's end", later.Err, StringComparison.Ordinal);
        Assert.Equal(manifest, File.ReadAllText(Path.Combine(output, "manifest.json")));
        Assert.Equal(notes, File.ReadAllText(Path.Combine(output, "release-notes.md")));

        CliHarness.Ok("--estate", root, "docs", "notes", "--from", "0.1.0", "--to", "0.2.0", "--out", output, "--since", "2026-09-01T00:09:43Z");
        using JsonDocument earlier = JsonDocument.Parse(File.ReadAllText(Path.Combine(output, "manifest.json")));
        Assert.Equal("2026-09-01T00:09:43Z", earlier.RootElement.GetProperty("notes").GetProperty("from").GetString());
        notes = File.ReadAllText(Path.Combine(output, "release-notes.md"));
        Assert.Contains("since 2026-09-01T00:09:43Z", notes, StringComparison.Ordinal);
        Assert.Contains("explicitly widened to include records missed by the previous set", notes, StringComparison.Ordinal);
        Assert.Contains("**W-0**", notes, StringComparison.Ordinal);
        Assert.Contains("**W-1**", notes, StringComparison.Ordinal);

        CliHarness.Ok("--estate", root, "docs", "notes", "--from", "0.1.0", "--to", "0.2.0", "--out", output, "--since", "2026-09-01T00:30:00Z");
        Assert.DoesNotContain("**W-0**", File.ReadAllText(Path.Combine(output, "release-notes.md")), StringComparison.Ordinal);
    }

    private static string Declaration(string directory)
    {
        string path = Path.Combine(directory, "..", "documents-" + Path.GetFileName(directory) + ".json");
        File.WriteAllText(path, JsonSerializer.Serialize(Declared));
        return path;
    }

    private static (int Code, string Text) Tool(Func<int> action)
    {
        var output = new StringWriter { NewLine = "\n" };
        TextWriter previous = Console.Out;
        Console.SetOut(output);
        try
        {
            return (action(), output.ToString().Trim());
        }
        finally
        {
            Console.SetOut(previous);
        }
    }
}
